import {esc} from './customer-shared.mjs';

const label={passed:'Verified',demo:'Demo evidence',recorded:'Recorded',running:'In progress',pending:'Waiting',failed:'Needs attention','needs-help':'Needs help','not-needed':'No change needed'};
const date=value=>value&&Number.isFinite(Date.parse(value))?new Date(value).toLocaleString():'Time not recorded';
const workflowName={gather:'Gather evidence',analyze:'Consult specialists',record:'Record findings',repair:'Apply approved correction',verify:'Verify protected lesson'};
export function passportMarkup(passport,{customer=false}={}){
 if(!passport)return '';
 const complete=passport.steps.filter(step=>step.status==='passed'||step.status==='demo'||step.status==='recorded'||step.status==='not-needed').length;
 const steps=passport.steps.map((step,index)=>`<li class="${esc(step.status)}"><span class="passport-number">${String(index+1).padStart(2,'0')}</span><div><div class="passport-step-title"><strong>${esc(step.title)}</strong><span>${esc(label[step.status]||step.status)}</span></div><p>${esc(step.detail)}</p><small>${esc(step.source)} · ${esc(date(step.at))}</small>${!customer&&step.reference?`<code>${esc(step.reference)}</code>`:''}${!customer&&step.sourceIds?.length?`<small>Saved sources: ${esc(step.sourceIds.join(', '))}</small>`:''}</div></li>`).join('');
 const workflow=customer?'':passport.workflow?`<section class="passport-workflow" aria-label="Render workflow steps"><div><span class="passport-kicker">RUN EXECUTION</span><h3>${passport.workflow.runId?'Render '+esc(passport.workflow.kind)+' run':'Workflow request'}</h3><p>${passport.workflow.runId?'Run ID '+esc(passport.workflow.runId):'No Render run ID was accepted.'} · Started ${esc(date(passport.workflow.startedAt))}</p></div><ol>${passport.workflow.stages.map(stage=>`<li class="${esc(stage.status)}"><span>${esc(stage.status==='complete'?'✓':stage.status==='failed'?'!':'·')}</span>${esc(workflowName[stage.name]||stage.name)}<small>${esc(stage.status)}</small></li>`).join('')}</ol>${passport.workflow.error?`<p role="status">${esc(passport.workflow.error)}</p>`:''}<small>A task run ID alone does not establish successful correction or verification.</small></section>`:'<p class="passport-workflow-empty">No Render task run is recorded for this case.</p>';
 const start=customer?`<details class="passport passport-customer" aria-label="Recovery Passport"><summary class="passport-customer-summary"><span class="passport-kicker">RECOVERY PASSPORT</span><strong>${esc(passport.headline)}</strong><small>${complete} of ${passport.steps.length} stages recorded · Open the evidence timeline</small></summary>`:'<section class="passport passport-merchant" aria-label="Recovery Passport">';
 return `${start}<div class="passport-head"><div><span class="passport-kicker">PAYTRACE / RECOVERY PASSPORT</span><h2>${esc(passport.headline)}</h2><p>${customer?'Follow what has been checked and what still needs attention. You can message the merchant below.':'A traceable account of the saved payment, decision, correction, and outcome.'}</p></div><div class="passport-count"><strong>${complete}<span> / ${passport.steps.length}</span></strong><small>stages recorded</small></div></div><div class="passport-meta"><span>${esc(passport.scope==='connected-sandbox'?'Connected sandbox evidence':passport.scope==='server-demo'?'Server demo evidence':'Browser simulation')}</span><span>Updated ${esc(date(passport.generatedAt))}</span></div><ol class="passport-steps">${steps}</ol>${workflow}<p class="passport-note">${esc(passport.note)}</p>${customer?'</details>':'</section>'}`;
}
